// Package dicomuid holds the Libre Systems DICOM UID root and its controlled
// layout (docs/qms/uid-registry.md, owner Patrick Mulcahy, approved
// 2026-11-17, issue #30):
//
//	1.3.6.1.4.1.67686                 root (IANA Private Enterprise Number 67686, Libre Systems)
//	1.3.6.1.4.1.67686.1.<p>           products: 1 LibreDCM, 2 Libre WT, 3 LibreDVT, 4 LibreKey
//	1.3.6.1.4.1.67686.1.<p>.1.<M>.<m> Implementation Class UID of product p, version M.m
//	1.3.6.1.4.1.67686.2.<p>.<site>.<time>.<counter>  UIDs generated by product p (Generator)
//	<root>.9                          test data only; never in shipped code paths
//
// The test-data arc is deliberately not a constant here and is not spelled
// out in shipped code at all (DCM-SRS-100, TestTestDataArcOnlyInTests).
package dicomuid

import (
	"errors"
	"fmt"
	"regexp"
	"strconv"
)

// Root is Libre Systems' UID root, built on IANA Private Enterprise Number
// 67686.
const Root = "1.3.6.1.4.1.67686"

// Arcs below Root.
const (
	ProductsArc  = Root + ".1" // product identification (Implementation Class UIDs)
	GeneratedArc = Root + ".2" // UIDs generated by products at run time
)

// Product is a product number under ProductsArc and GeneratedArc.
type Product int

// Product numbers (uid-registry.md §3). Never renumber or reuse.
const (
	LibreDCM Product = 1
	LibreWT  Product = 2
	LibreDVT Product = 3
	LibreKey Product = 4
)

// name is the product's Implementation Version Name prefix.
func (p Product) name() string {
	switch p {
	case LibreDCM:
		return "LIBREDCM"
	case LibreWT:
		return "LIBREWT"
	case LibreDVT:
		return "LIBREDVT"
	case LibreKey:
		return "LIBREKEY"
	}
	return ""
}

// Valid reports whether p is an allocated product number.
func (p Product) Valid() bool { return p.name() != "" }

// maxVersionPart keeps <NAME>_<major>_<minor> within the 16 characters VR SH
// allows for the longest name (LIBREDCM_999_999).
const maxVersionPart = 999

var versionRE = regexp.MustCompile(`^v?(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(?:[.+-].*)?$`)

// ParseVersion returns the major and minor numbers of a build version such
// as "0.2.0", "v0.2.0-beta.1" or "0.2.0-beta.1-12-gabc123". A version that
// is not of that form ("dev", "ci", "") or that has a part above 999 gives
// 0.0, ok=false: such builds identify as the never-released version 0.0.
func ParseVersion(version string) (major, minor int, ok bool) {
	m := versionRE.FindStringSubmatch(version)
	if m == nil {
		return 0, 0, false
	}
	major, err1 := strconv.Atoi(m[1])
	minor, err2 := strconv.Atoi(m[2])
	if err1 != nil || err2 != nil || major > maxVersionPart || minor > maxVersionPart {
		return 0, 0, false
	}
	return major, minor, true
}

// Implementation returns the Implementation Class UID (PS3.7 D.3.3.2) and
// Implementation Version Name of product p built as version:
// 1.3.6.1.4.1.67686.1.<p>.1.<major>.<minor> and <NAME>_<major>_<minor>.
// It panics for an unallocated product: that is a programming error.
func Implementation(p Product, version string) (classUID, versionName string) {
	if !p.Valid() {
		panic(fmt.Sprintf("dicomuid: product %d is not allocated", p))
	}
	major, minor, _ := ParseVersion(version)
	classUID = fmt.Sprintf("%s.%d.1.%d.%d", ProductsArc, p, major, minor)
	versionName = fmt.Sprintf("%s_%d_%d", p.name(), major, minor)
	return classUID, versionName
}

// MaxLen is the longest UID PS3.5 §9.1 allows.
const MaxLen = 64

// ErrInvalid is returned by Valid for a value that is not a valid UID.
var ErrInvalid = errors.New("dicomuid: invalid UID")

// Valid checks the PS3.5 §9.1 rules: 1 to 64 characters, only digits and
// dots, no empty component, and no leading zero in a component of more than
// one digit.
func Valid(uid string) error {
	if uid == "" || len(uid) > MaxLen {
		return fmt.Errorf("%w: length %d (1..%d)", ErrInvalid, len(uid), MaxLen)
	}
	start := 0
	for i := 0; i <= len(uid); i++ {
		if i < len(uid) && uid[i] != '.' {
			if uid[i] < '0' || uid[i] > '9' {
				return fmt.Errorf("%w: character %q at %d", ErrInvalid, uid[i], i)
			}
			continue
		}
		comp := uid[start:i]
		if comp == "" {
			return fmt.Errorf("%w: empty component at %d", ErrInvalid, start)
		}
		if len(comp) > 1 && comp[0] == '0' {
			return fmt.Errorf("%w: leading zero in component %q", ErrInvalid, comp)
		}
		start = i + 1
	}
	return nil
}
